<?php $title='Create account';require 'includes/header.php';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$pass=$_POST['password']??'';if(!$name||!$email||!$phone||!$address||strlen($pass)<8)$errors[]='Please complete all fields; password needs 8 characters.';if($pass!==($_POST['confirm_password']??''))$errors[]='Passwords do not match.';if($pdo&&!$errors){$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())$errors[]='That email address is already registered.';else{$q=$pdo->prepare('INSERT INTO users(name,email,phone,address,password) VALUES(?,?,?,?,?)');$q->execute([$name,$email,$phone,$address,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['flash']='Account created. Please sign in.';header('Location: '.url('login.php'));exit;}}} ?>
<div class="card auth-card p-4 p-md-5"><h2 class="section-title">Create your account</h2><p class="text-muted">Your next great find is waiting.</p><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post" class="row g-3" novalidate><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-12"><label class="form-label">Full name</label><input required name="name" class="form-control"></div><div class="col-md-6"><label class="form-label">Email</label><input required type="email" name="email" class="form-control"></div><div class="col-md-6"><label class="form-label">Phone number</label><input required name="phone" class="form-control"></div><div class="col-12"><label class="form-label">Address</label><textarea required name="address" class="form-control"></textarea></div><div class="col-md-6"><label class="form-label">Password</label><input required minlength="8" type="password" name="password" class="form-control"></div><div class="col-md-6"><label class="form-label">Confirm password</label><input required type="password" name="confirm_password" class="form-control"></div><div class="col-12"><button class="btn btn-primary w-100 rounded-pill">Create account</button></div></form><p class="text-center mt-3 mb-0">Already a member? <a href="<?=url('login.php')?>">Sign in</a></p></div><?php require 'includes/footer.php'; ?>
